"""Camera-guided controller for one real-robot-style episode.
No resets, object state, demonstrations, or success queries.
"""
import argparse,json,pathlib,time
import numpy as np
from scipy.spatial.transform import Rotation
from scipy.optimize import least_squares
from rcb_client import Robot
from PIL import Image,ImageDraw
OUT=pathlib.Path('/app/output')
CAMS=['robot0_agentview_center','robot0_agentview_left','robot0_agentview_right','robot0_eye_in_hand']
def rx(a):
 c,s=np.cos(a),np.sin(a); return np.array([[1,0,0],[0,c,-s],[0,s,c]])
def rz(a):
 c,s=np.cos(a),np.sin(a); return np.array([[c,-s,0],[s,c,0],[0,0,1]])
def fk(q):
 T=np.eye(4)
 for qi,a,d,al in zip(q,[0,0,0,.0825,-.0825,0,.088],[.333,0,.316,0,.384,0,.107],[0,-np.pi/2,np.pi/2,np.pi/2,-np.pi/2,np.pi/2,np.pi/2]):
  A=np.eye(4); A[:3,:3]=rx(al)@rz(qi); A[:3,3]=np.array([a,0,0])+rx(al)@np.array([0,0,d]); T=T@A
 return T
class Controller:
 def __init__(self):
  self.r=Robot(); self.spec=self.r.spec(); self.dt=self.spec['control_dt']; self.obs=self.r.get_obs(cameras=CAMS,include_depth=True,video='none'); self.update()
  self.seq=len(list((OUT/'runs').glob('*'))) if (OUT/'runs').exists() else 0
  self.cal=json.load(open(OUT/'calibration.json')) if (OUT/'calibration.json').exists() else None
 def update(self):
  self.p=np.array(self.obs.meta['proprio']['now']); self.q=self.p[4:11].copy(); self.eef=self.p[26:29].copy()
 def save(self,note):
  self.seq+=1; folder=OUT/'runs'/f'{self.seq:03d}_{note}'; self.obs.save(str(folder))
  canvas=Image.new('RGB',(640,480))
  for i,c in enumerate(CAMS):
   if c in self.obs.last:
    im=Image.fromarray(self.obs.last[c]); ImageDraw.Draw(im).text((3,3),c.replace('robot0_',''),fill='red'); canvas.paste(im,(i%2*320,i//2*240))
  canvas.save(OUT/'latest.jpg'); print('RUN',folder,flush=True)
  print('Q',self.q,'EEF',self.eef,'FINGERS',self.p[11:13],'TIME',self.obs.meta.get('time_left_s'),flush=True)
 def run(self,A,note,cameras=CAMS):
  A=np.asarray(A,float); np.save(OUT/f'actions_{self.seq+1:03d}.npy',A)
  self.obs=self.r.submit('joint_position',A,cameras=cameras,video='none',include_depth=True,note=note); self.update(); self.save(note)
 def moveq(self,q,seconds=1.5,grip=None,base=None,torso=0,mode=-1,note='move'):
  n=round(seconds/self.dt); A=np.zeros((n,13)); A[:,:7]=np.linspace(self.q,q,n); A[:,7]=self.p[36] if grip is None else grip; A[:,12]=mode
  if base is not None: A[:,8:11]=base
  A[:,11]=torso; self.run(A,note)
 def observe(self,note='observe',seconds=0):
  self.obs=self.r.get_obs(cameras=CAMS,seconds=seconds,include_depth=True,video='none'); self.update(); self.save(note)
 def point(self,c,u,v):
  dep=self.obs.depth[c]; dep=dep[-1] if dep.ndim==3 else dep; K=np.array(self.obs.meta['cameras'][c]['intrinsic_cv']); T=np.array(self.obs.meta['cameras'][c]['cam2world_gl']); d=float(dep[v,u]); return T[:3,3]+T[:3,:3]@np.array([(u-K[0,2])*d/K[0,0],-(v-K[1,2])*d/K[1,1],-d])
 def predict(self,q):
  T=fk(q); R=np.array(self.cal['R']); t=np.array(self.cal['t']); tool=np.array(self.cal['tool']); return R@(T[:3,3]+T[:3,:3]@tool)+t,R@T[:3,:3]
 def ik(self,target,rot=None):
  target=np.array(target); q0=self.q.copy()
  def fun(q):
   p,R=self.predict(q); vals=[(p-target)*5]
   if rot is not None: vals.append(Rotation.from_matrix(R@np.array(rot).T).as_rotvec()*.5)
   vals.append((q-q0)*.015); return np.concatenate(vals)
  res=least_squares(fun,q0,bounds=([-2.89,-1.75,-2.89,-3.06,-2.89,-.01,-2.89],[2.89,1.75,2.89,-.07,2.89,3.75,2.89]),max_nfev=300)
  print('IK',target,'pred',self.predict(res.x)[0],'q',res.x,'error',np.linalg.norm(self.predict(res.x)[0]-target),flush=True); return res.x
 def moveto(self,target,rot=None,seconds=1.5,grip=None,note='cartesian'):
  self.moveq(self.ik(target,rot),seconds,grip=grip,note=note)
if __name__=='__main__':
 ap=argparse.ArgumentParser(); ap.add_argument('command',choices=['obs','q','xyz','hold']); ap.add_argument('values',nargs='*',type=float); ap.add_argument('--seconds',type=float,default=1.5); ap.add_argument('--grip',type=float); ap.add_argument('--note',default='manual'); ap.add_argument('--rot',nargs=3,type=float); args=ap.parse_args(); c=Controller()
 if args.command=='obs': c.observe(args.note)
 if args.command=='hold': c.moveq(c.q,args.seconds,grip=args.grip,note=args.note)
 if args.command=='q': c.moveq(np.array(args.values),args.seconds,grip=args.grip,note=args.note)
 if args.command=='xyz':
  rot=c.predict(c.q)[1] if args.rot is None else Rotation.from_euler('xyz',args.rot).as_matrix(); c.moveto(args.values,rot,args.seconds,args.grip,args.note)
